    }
    ctx.putImageData(imageData, 0, 0);
  }

  // Simulation step — returns nothing, modifies grid in place
  function step() {
    // Process bottom-to-top, randomize x direction
    for (let y = H - 1; y >= 0; y--) {
      // Randomize left-right order per row
      const shuffle = Math.random() < 0.5;
      const startX = shuffle ? 0 : W - 1;
      const endX = shuffle ? W : -1;
      const stepDir = shuffle ? 1 : -1;

      for (let x = startX; x !== endX; x += stepDir) {
        const ci = idx(x, y);
        const type = grid[ci];

        if (type === EMPTY || type === WALL) continue;

        if (type === SAND || type === WATER || type === ACID) {
          // Try to move down
          let moved = false;
          if (y < H - 1) {
            const below = idx(x, y + 1);
            const belowType = grid[below];

            if (type === SAND && (belowType === WATER || belowType === ACID)) {
              // Sand sinks: swap with liquid
              grid[ci] = belowType;
              grid[below] = SAND;
              continue;
            } else if ((type === WATER || type === ACID) && belowType === SAND) {
              // Water/acid can't go through sand directly; check if they can swap
              // Sand falls into empty space, water flows around
            }

            if (belowType === EMPTY || (type !== SAND && belowType === SAND)) {
              if (type !== WATER || belowType !== SAND) {
                grid[ci] = EMPTY;
                grid[below] = type;
                moved = true;
                continue;
              }
            }

            // Acid dissolves adjacent sand/wall before trying to move
            if (type === ACID) {
              // Try below
              if (y < H - 1 && (grid[idx(x, y+1)] === SAND || grid[idx(x, y+1)] === WALL)) {
                if (Math.random() < 0.3) {
                  grid[idx(x, y+1)] = EMPTY;
                  if (Math.random() < 0.5) {
                    grid[ci] = EMPTY; // acid consumed
                  }
                  continue;
                }
              }
              // Try left
              if (x > 0 && (grid[idx(x-1, y)] === SAND || grid[idx(x-1, y)] === WALL)) {
                if (Math.random() < 0.3) {
                  grid[idx(x-1, y)] = EMPTY;
                  if (Math.random() < 0.5) {
                    grid[ci] = EMPTY;
                  }
                  continue;
                }
              }
              // Try right
              if (x < W - 1 && (grid[idx(x+1, y)] === SAND || grid[idx(x+1, y)] === WALL)) {
                if (Math.random() < 0.3) {
                  grid[idx(x+1, y)] = EMPTY;
                  if (Math.random() < 0.5) {
