              const dir2 = -dir1;
              for (let di = 0; di < 2; di++) {
                const d = di === 0 ? dir1 : dir2;
                if (x + d >= 0 && x + d < W) {
                  const diag = idx(x + d, y + 1);
                  const dt = grid[diag];
                  if (dt === EMPTY) {
                    grid[ci] = EMPTY;
                    grid[diag] = SAND;
                    moved = true;
                    break;
                  } else if (type !== WATER && dt !== WALL) {
                    // Swap with water/acid below-diagonal
                    grid[ci] = dt;
                    grid[diag] = SAND;
                    moved = true;
                    break;
                  }
                }
              }
              if (moved) continue;

              // Sand can't move, stays put (if blocked by wall on both sides, or below is filled)
              // Check if below is sand/water/acid - it will stay. If below is wall/block, check diagonals again for swap
              // Already handled above: tried diagonal down. If those fail too, just fall through to horizontal spread (none for sand).
            } else if (type === WATER || type === ACID) {
              // Try to move into a liquid cell below (water/acid below - rare but possible with swaps)
              if (y < H - 1 && grid[idx(x, y+1)] !== EMPTY && grid[idx(x, y+1)] !== WALL) {
                // Could try to flow through? No, sand blocks. Let's just try horizontal spread.
              }

              // Horizontal spread for water/acid when they can't fall
              if (!moved) {
                const spreadDirs = [];
                if (x > 0) spreadDirs.push(-1);
                if (x < W - 1) spreadDirs.push(1);
                if (spreadDirs.length === 2) {
                  // Randomize order
