                  else { spreadDirs[0] = 1; spreadDirs[1] = -1; }
                }

                for (let si = 0; si < spreadDirs.length; si++) {
                  const nx = x + spreadDirs[si];
                  if (nx >= 0 && nx < W) {
                    // Find the furthest empty cell horizontally
                    let furthest = nx;
                    let fy = y;
                    for (let k = nx; k >= 0 && k < W; ) {
                      const nk = grid[idx(k, y)];
                      if (nk === EMPTY) {
                        furthest = k;
                        // Look further in same direction
                        break;
                      } else if (nk === WALL || nk === SAND) {
                        break;
                      }
                      k += spreadDirs[si];
                    }

                    // Try to fill empty cells along the way
