                          for (let lz = Math.min(nx, furthest); lz <= Math.max(nx, furthest); lz++) {
                            if (grid[idx(lz, y)] === EMPTY) {
                              // Don't fill - we'll move one cell at a time
                            }
                          }
                          break;
                        }
                      }
                      break;
                    }

                    // Simple: just try to move into the adjacent empty cell
                    if (grid[idx(nx, y)] === EMPTY) {
                      grid[ci] = EMPTY;
                      grid[idx(nx, y)] = type;
                      moved = true;
                      break;
                    } else {
                      // Fill in a gap: scan further
                      let fx = nx;
                      while (fx >= 0 && fx < W && grid[idx(fx, y)] === EMPTY) {
                        fx += spreadDirs[si];
                      }
                      if (fx !== nx && grid[idx(fx - spreadDirs[si], y)] === EMPTY) {
                        // Found an empty spot further away — fill the path
                        for (let pz = nx; pz !== fx; pz -= spreadDirs[si]) {
                          grid[idx(pz, y)] = type;
                        }
                        grid[ci] = EMPTY;
                        moved = true;
                        break;
                      }
                    }
                  }
                }
              }
            }

            // Acid: after trying to move down, try horizontal spread (like water)
            if (type === ACID && !moved) {
              const spreadDirs = [];
              if (x > 0) spreadDirs.push(-1);
              if (x < W - 1) spreadDirs.push(1);
              if (spreadDirs.length === 2 && Math.random() < 0.5) {
