                if (Math.random() < 0.3) {
                  grid[idx(x-1, y)] = EMPTY;
                  if (Math.random() < 0.5) grid[ci] = EMPTY;
                }
              }
              if (x < W - 1 && (grid[idx(x+1, y)] === SAND || grid[idx(x+1, y)] === WALL)) {
                if (Math.random() < 0.3) {
                  grid[idx(x+1, y)] = EMPTY;
                  if (Math.random() < 0.5) grid[ci] = EMPTY;
                }
              }
            }

            // Horizontal spread for water/acid at bottom
            if (type === WATER || type === ACID) {
              const spreadDirs = [];
              if (x > 0) spreadDirs.push(-1);
              if (x < W - 1) spreadDirs.push(1);
              if (spreadDirs.length === 2 && Math.random() < 0.5) {
                const tmp = spreadDirs[0]; spreadDirs[0] = spreadDirs[1]; spreadDirs[1] = tmp;
              }

              for (let si = 0; si < spreadDirs.length; si++) {
                const nx = x + spreadDirs[si];
                if (nx >= 0 && nx < W) {
                  let fx = nx;
                  while (fx >= 0 && fx < W && grid[idx(fx, y)] === EMPTY) {
                    fx += spreadDirs[si];
                  }
                  if (grid[idx(fx - spreadDirs[si], y)] === EMPTY) {
                    for (let pz = nx; pz !== fx; pz -= spreadDirs[si]) {
                      grid[idx(pz, y)] = type;
                    }
                    grid[ci] = EMPTY;
                  }
                }
              }
            }
          }
        }
      }
    }
  }

  // Better step function — let me rewrite it properly for correctness
  function simulateStep() {
    // We process bottom-to-top so particles move at most one cell per step
    // Within each row, we randomize x direction to avoid left/right bias
    const randLR = Math.random() < 0.5;

    for (let y = H - 1; y >= 0; y--) {
      const leftToRight = randLR || Math.random() < 0.5;
      const xs = [];
      if (leftToRight) {
        for (let x = 0; x < W; x++) xs.push(x);
      } else {
        for (let x = W - 1; x >= 0; x--) xs.push(x);
      }

      // Create a copy of this row so we can check neighbors without interference?
      // Actually in CA each cell updates based on the current grid state.
      // But to avoid ordering bias, some implementations use nextGrid. 
      // However the spec says "process movement bottom-row-up" which implies single grid.
      // We'll use single grid with careful ordering.

      for (let xi = 0; xi < xs.length; xi++) {
        const x = xs[xi];
        const ci = idx(x, y);
        const type = grid[ci];

        if (type === EMPTY || type === WALL) continue;

        if (type === SAND) {
          // Try down
          if (y < H - 1) {
            const bi = idx(x, y + 1);
            const bt = grid[bi];
            if (bt === EMPTY) {
