              grid[ci] = bt; grid[bi] = SAND;
              continue;
            }
          }

          // Try diagonal down-left, down-right
          const dirs = [Math.random() < 0.5 ? -1 : 1, Math.random() < 0.5 ? 1 : -1];
          for (let d = 0; d < 2; d++) {
            const nx = x + dirs[d];
            if (nx >= 0 && nx < W && y < H - 1) {
              const ni = idx(nx, y + 1);
              const nt = grid[ni];
              if (nt === EMPTY || nt === WATER || nt === ACID) {
                grid[ci] = nt; grid[ni] = SAND;
                break;
              } else if (nt === WALL && y < H - 2) {
                // Try to swap into liquid below the wall? No, walls are solid.
              }
            }
          }
        } else if (type === WATER || type === ACID) {
          let didMove = false;

          // Down move
          if (y < H - 1) {
            const bi = idx(x, y + 1);
            const bt = grid[bi];
            if (bt === EMPTY) {
              grid[ci] = EMPTY; grid[bi] = type;
              didMove = true;
            } else if (type === ACID && (bt === SAND || bt === WALL)) {
              // Acid dissolves adjacent sand/wall
              if (Math.random() < 0.15) {
                grid[bi] = EMPTY;
                if (Math.random() < 0.4) {
                  grid[ci] = EMPTY; // acid consumed
                }
              }
            } else if (type === WATER && bt === SAND) {
              // Water can flow through sand? No, let's keep it simple: water moves past sand cells too slowly
              // Actually, in falling sand, water flows through and around. Let's have water displace into empty space below even through sand.
              // Simpler: just don't do anything here if blocked by sand. Water will flow horizontally instead.
            }
          }

          if (!didMove) {
            // Horizontal spread for water/acid
            const hDirs = [];
            if (x > 0) hDirs.push(-1);
            if (x < W - 1) hDirs.push(1);

            // Randomize direction priority
            if (hDirs.length === 2 && Math.random() < 0.5) {
              const t = hDirs[0]; hDirs[0] = hDirs[1]; hDirs[1] = t;
            }

            for (let di = 0; di < hDirs.length; di++) {
              let nx = x + hDirs[di];
              if (nx >= 0 && nx < W) {
                // Scan forward to find empty cells
                let furthestX = -1;
                while (nx >= 0 && nx < W) {
                  if (grid[idx(nx, y)] === EMPTY) {
                    furthestX = nx;
                  } else if (grid[idx(nx, y)] === WALL || grid[idx(nx, y)] === SAND) {
                    break;
                  }
                  // If it's another water/acid cell, we can't pass through in this simplified model
                  nx += hDirs[di];
                }

                if (furthestX >= 0 && furthestX !== x) {
                  // Fill path from current position to furthest
                  const fillStart = Math.min(x, furthestX);
                  const fillEnd = Math.max(x, furthestX);
                  for (let fz = fillStart; fz <= fillEnd; fz++) {
                    if (fz !== x && grid[idx(fz, y)] === EMPTY) {
                      grid[idx(fz, y)] = type; // Fill with the same liquid
                    }
                  }
                  grid[ci] = EMPTY;
                  didMove = true;
                  break;
                }
              }
            }

            // Acid: dissolve left/right neighbors
            if (type === ACID && !didMove) {
              for (let di2 = -1; di2 <= 1; di2 += 2) {
                const nx2 = x + di2;
                if (nx2 >= 0 && nx2 < W) {
                  const ni2 = idx(nx2, y);
                  const nt2 = grid[ni2];
                  if (nt2 === SAND || nt2 === WALL) {
                    if (Math.random() < 0.15) {
                      grid[ni2] = EMPTY;
                      if (Math.random() < 0.4) grid[ci] = EMPTY;
                    }
                  }
                }
              }
            }
          }

          // Acid dissolve below check even when moved
          if (type === ACID && !didMove && y < H - 1) {
            const ni = idx(x, y + 1);
            const nt = grid[ni];
            if (nt === SAND || nt === WALL) {
              if (Math.random() < 0.15) {
                grid[ni] = EMPTY;
                if (Math.random() < 0.4) grid[ci] = EMPTY;
              }
            }
          }
        }
      }
    }
  }

  // Even cleaner simulation — let me redo this one more time for maximum correctness
  function simTick() {
    const rng = Math.random();
    const flipX = rng < 0.5; // deterministic-ish per-step direction

    for (let y = H - 1; y >= 0; y--) {
      // Alternate scan direction each row to avoid bias
      const rowFlip = (y + Math.floor(rng * 10)) % 2 === 0;
      const xStart = rowFlip ? 0 : W - 1;
      const xEnd = rowFlip ? W : -1;
      const xStep = rowFlip ? 1 : -1;

      for (let x = xStart; x !== xEnd; x += xStep) {
        const i = idx(x, y);
        const t = grid[i];

        if (t === EMPTY || t === WALL) continue;

        if (t === SAND) {
          // Fall down
          if (y + 1 < H) {
            const bi = i + W;
            const bt = grid[bi];
            if (bt === EMPTY) { grid[i] = EMPTY; grid[bi] = SAND; }
            else if (bt === WATER || bt === ACID) { grid[i] = bt; grid[bi] = SAND; }
          }

          // Diagonal slide
          if (grid[i] === SAND) { // still sand?
            const d1 = Math.random() < 0.5 ? -1 : 1;
            const d2 = -d1;
            for (let di = 0; di < 2; di++) {
              const dx = di === 0 ? d1 : d2;
              const nx = x + dx;
              if (nx >= 0 && nx < W && y + 1 < H) {
                const ni = idx(nx, y + 1);
                const nt = grid[ni];
                if (nt === EMPTY || nt === WATER || nt === ACID) {
                  grid[i] = nt; grid[ni] = SAND;
                  break;
                }
              }
            }
          }
        }

        if (t === WATER || t === ACID) {
          const type = grid[i]; // re-read in case it changed
          if (type !== WATER && type !== ACID) continue;

          let moved = false;

          // Down
          if (y + 1 < H) {
            const bi = i + W;
            const bt = grid[bi];
            if (bt === EMPTY) {
              grid[i] = EMPTY; grid[bi] = type;
              moved = true;
            } else if (type === ACID && (bt === SAND || bt === WALL)) {
