                grid[bi] = EMPTY;
                if (Math.random() < 0.5) grid[i] = EMPTY;
              }
            } else if (type === WATER && bt !== WALL) {
              // Water flows through sand cells too
              // Let water replace sand below it occasionally
              if (bt === SAND && Math.random() < 0.02) {
                // Very slow percolation - actually let's not do this
                // It causes weirdness. Just don't move down through sand.
              }
            }
          }

          if (!moved) {
            // Horizontal spread
            const dirs = [];
            if (x > 0) dirs.push(-1);
